import{_ as e,c as a,o as t,a2 as o}from"./chunks/framework.BQGPkCej.js";const _=JSON.parse('{"title":"更新 bot","description":"","frontmatter":{},"headers":[],"relativePath":"deploy/use/update.md","filePath":"deploy/use/update.md","lastUpdated":1720634491000}'),i={name:"deploy/use/update.md"},s=o('<h1 id="更新-bot" tabindex="-1">更新 bot <a class="header-anchor" href="#更新-bot" aria-label="Permalink to &quot;更新 bot&quot;">​</a></h1><p>通常需要更新 bot 本体源码来使用新增功能，或是解决现存问题。存在下面几种更新方式。</p><h2 id="zip覆盖更新" tabindex="-1">zip覆盖更新 <a class="header-anchor" href="#zip覆盖更新" aria-label="Permalink to &quot;zip覆盖更新&quot;">​</a></h2><p>打开项目仓库，自行下载 <code>zip</code> 文件覆盖更新。</p><p>这种方式极为不推荐，繁琐不谈，且无法使用 bot 提供的一系列便利的更新方式。</p><p><s>但这种方式不用担心网络问题</s></p><h2 id="手动git更新" tabindex="-1">手动git更新 <a class="header-anchor" href="#手动git更新" aria-label="Permalink to &quot;手动git更新&quot;">​</a></h2><p>进入 bot 根目录，执行 git 命令手动拉取更新</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span></span></code></pre></div><h2 id="指令更新" tabindex="-1">指令更新 <a class="header-anchor" href="#指令更新" aria-label="Permalink to &quot;指令更新&quot;">​</a></h2><p>当使用 <code>pm2</code> 或是 <code>docker</code> 方式启动，且非 zip 安装项目时，支持通过向 bot 发送指令的方式更新源码。</p><p>以默认指令起始符与指令名为例，向 bot 发送 <code>#upgrade</code> 等待片刻即可完成更新。</p><h2 id="网页控制台更新" tabindex="-1">网页控制台更新 <a class="header-anchor" href="#网页控制台更新" aria-label="Permalink to &quot;网页控制台更新&quot;">​</a></h2><p>打开网页控制台后，在右上角存在按钮 <code>更新bot</code>，点击即可完成更新。</p><p>该方式同样要求项目使用 <code>pm2</code> 或是 <code>docker</code> 方式启动，且非通过 zip 安装。</p>',15),d=[s];function p(c,r,l,n,h,u){return t(),a("div",null,d)}const k=e(i,[["render",p]]);export{_ as __pageData,k as default};
